use super::Subprocess;
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use serde_json::Value;

#[derive(Debug, Deserialize)]
struct VectorSet {
    #[serde(rename = "vsId")]
    vs_id: u64,
    algorithm: String,
    revision: String,
    mode: Mode,
    #[serde(rename = "testGroups")]
    test_groups: Vec<TestGroup>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
enum Mode {
    KeyGen,
    EncapDecap,
}

#[derive(Debug, Deserialize)]
struct TestGroup {
    #[serde(rename = "tgId")]
    tg_id: u64,
    #[serde(rename = "parameterSet")]
    parameter_set: String,
    function: Option<Function>,
    tests: Vec<TestCase>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
enum Function {
    Encapsulation,
    Decapsulation,
    EncapsulationKeyCheck,
    DecapsulationKeyCheck,
}

#[derive(Debug, Deserialize)]
struct TestCase {
    #[serde(rename = "tcId")]
    tc_id: u64,
    seed: Option<String>,
    ek: Option<String>,
    dk: Option<String>,
    m: Option<String>,
    ct: Option<String>,
}

#[derive(Serialize)]
struct Response {
    #[serde(rename = "vsId")]
    vs_id: u64,
    algorithm: String,
    revision: String,
    #[serde(rename = "testGroups")]
    test_groups: Vec<ResponseGroup>,
}

#[derive(Serialize)]
struct ResponseGroup {
    #[serde(rename = "tgId")]
    tg_id: u64,
    tests: Vec<ResponseTest>,
}

#[derive(Serialize)]
struct ResponseTest {
    #[serde(rename = "tcId")]
    tc_id: u64,
    #[serde(skip_serializing_if = "Option::is_none")]
    ek: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    dk: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    c: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    k: Option<String>,
    #[serde(rename = "testPassed", skip_serializing_if = "Option::is_none")]
    test_passed: Option<bool>,
}

fn decode_hex(value: Option<&str>, field: &str) -> Result<Vec<u8>> {
    let value = value.with_context(|| format!("Missing {field}"))?;
    hex::decode(value).with_context(|| format!("Invalid hex in {field}"))
}

fn decode_ciphertext(test: &TestCase) -> Result<Vec<u8>> {
    let ct = test.ct.as_deref().context("Missing ct")?;
    // Preserve the original adapter's error label for malformed ciphertexts.
    hex::decode(ct).context("Invalid hex in c")
}

fn one_result<'a>(results: &'a [Vec<u8>], command: &str) -> Result<&'a [u8]> {
    if results.len() != 1 {
        anyhow::bail!(
            "{command} returned {} results; expected exactly one",
            results.len()
        );
    }
    Ok(&results[0])
}

fn two_results<'a>(results: &'a [Vec<u8>], command: &str) -> Result<(&'a [u8], &'a [u8])> {
    if results.len() != 2 {
        anyhow::bail!(
            "{command} returned {} results; expected exactly two",
            results.len()
        );
    }
    Ok((&results[0], &results[1]))
}

fn check_passed(result: &[u8]) -> Result<bool> {
    match result {
        [0x00] => Ok(false),
        [0x01] => Ok(true),
        _ => anyhow::bail!("Unexpected result from key check: {:?}", result),
    }
}

pub fn process_hqckem(subprocess: &mut Subprocess, vector_set: &Value) -> Result<Value> {
    let vector_set: VectorSet =
        serde_json::from_value(vector_set.clone()).context("Invalid HQC-KEM vector set")?;
    let mut response_groups = Vec::with_capacity(vector_set.test_groups.len());

    for group in &vector_set.test_groups {
        let mut response_tests = Vec::with_capacity(group.tests.len());

        for test in &group.tests {
            let response_test = match vector_set.mode {
                Mode::KeyGen => {
                    let seed = decode_hex(test.seed.as_deref(), "seed")?;
                    let results = subprocess
                        .transact("HQC-KEM/keyGen", &[group.parameter_set.as_bytes(), &seed])?;
                    if subprocess.check_unsupported(
                        &results,
                        &format!("HQC-KEM/keyGen for parameterSet={}", group.parameter_set),
                    ) {
                        continue;
                    }
                    let (ek, dk) = two_results(&results, "HQC-KEM/keyGen")?;
                    ResponseTest {
                        tc_id: test.tc_id,
                        ek: Some(hex::encode(ek)),
                        dk: Some(hex::encode(dk)),
                        c: None,
                        k: None,
                        test_passed: None,
                    }
                }
                Mode::EncapDecap => {
                    let function = group.function.as_ref().context("Missing function")?;
                    match function {
                        Function::Encapsulation => {
                            let ek = decode_hex(test.ek.as_deref(), "ek")?;
                            let m = decode_hex(test.m.as_deref(), "m")?;
                            let results = subprocess.transact(
                                "HQC-KEM/encaps",
                                &[group.parameter_set.as_bytes(), &ek, &m],
                            )?;
                            if subprocess.check_unsupported(
                                &results,
                                &format!("HQC-KEM/encaps for parameterSet={}", group.parameter_set),
                            ) {
                                continue;
                            }
                            let (c, k) = two_results(&results, "HQC-KEM/encaps")?;
                            ResponseTest {
                                tc_id: test.tc_id,
                                ek: None,
                                dk: None,
                                c: Some(hex::encode(c)),
                                k: Some(hex::encode(k)),
                                test_passed: None,
                            }
                        }
                        Function::Decapsulation => {
                            let dk = decode_hex(test.dk.as_deref(), "dk")?;
                            let ct = decode_ciphertext(test)?;
                            let results = subprocess.transact(
                                "HQC-KEM/decaps",
                                &[group.parameter_set.as_bytes(), &dk, &ct],
                            )?;
                            if subprocess.check_unsupported(
                                &results,
                                &format!("HQC-KEM/decaps for parameterSet={}", group.parameter_set),
                            ) {
                                continue;
                            }
                            let k = one_result(&results, "HQC-KEM/decaps")?;
                            ResponseTest {
                                tc_id: test.tc_id,
                                ek: None,
                                dk: None,
                                c: None,
                                k: Some(hex::encode(k)),
                                test_passed: None,
                            }
                        }
                        Function::EncapsulationKeyCheck => {
                            let ek = decode_hex(test.ek.as_deref(), "ek")?;
                            let results = subprocess.transact(
                                "HQC-KEM/encapsulationKeyCheck",
                                &[group.parameter_set.as_bytes(), &ek],
                            )?;
                            let passed = check_passed(one_result(
                                &results,
                                "HQC-KEM/encapsulationKeyCheck",
                            )?)?;
                            ResponseTest {
                                tc_id: test.tc_id,
                                ek: None,
                                dk: None,
                                c: None,
                                k: None,
                                test_passed: Some(passed),
                            }
                        }
                        Function::DecapsulationKeyCheck => {
                            let dk = decode_hex(test.dk.as_deref(), "dk")?;
                            let results = subprocess.transact(
                                "HQC-KEM/decapsulationKeyCheck",
                                &[group.parameter_set.as_bytes(), &dk],
                            )?;
                            let passed = check_passed(one_result(
                                &results,
                                "HQC-KEM/decapsulationKeyCheck",
                            )?)?;
                            ResponseTest {
                                tc_id: test.tc_id,
                                ek: None,
                                dk: None,
                                c: None,
                                k: None,
                                test_passed: Some(passed),
                            }
                        }
                    }
                }
            };
            response_tests.push(response_test);
        }
        response_groups.push(ResponseGroup {
            tg_id: group.tg_id,
            tests: response_tests,
        });
    }
    serde_json::to_value(Response {
        vs_id: vector_set.vs_id,
        algorithm: vector_set.algorithm,
        revision: vector_set.revision,
        test_groups: response_groups,
    })
    .context("Failed to serialize HQC-KEM response")
}

#[cfg(test)]
mod tests {
    use super::super::Subprocess;
    use super::process_hqckem;
    use serde_json::json;
    use std::path::Path;

    // FIPS-207 HQC-KEM known-answer test vectors (TC 1, decapsulation), from
    // crypto-test-vectors/vectors/custom/FIPS-207-pre-ipd/encapDecap.
    const DK_128: &str = "";
    const CT_128: &str = "";
    const K_128: &str = "56321ED955C76C4D3D9429501505E6B38037FE33F10B779EF5977190B5F4004B";

    const DK_192: &str = "";
    const CT_192: &str = "";
    const K_192: &str = "5E5AEA663E602462FE4750392B7AAB8FAB4C0D76546B8E2ABA6E8A8C254E34BD";

    const DK_256: &str = "";
    const CT_256: &str = "";
    const K_256: &str = "79B1D284DAA69112FEA8323F7D4C60BD3C862CD500661ADCF335C60B92B6ABAF";

    fn start_wrapper() -> Subprocess {
        // CARGO_BIN_EXE_* is only available in integration tests; for unit tests
        // we locate the binary relative to the running test executable.
        let mut path = std::env::current_exe().expect("cannot resolve test exe");
        path.pop(); // remove test binary name
        if path.ends_with("deps") {
            path.pop(); // step out of deps/ into target/debug (or release)
        }
        path.push("hqckem_wrapper");
        Subprocess::new(Path::new(&path), None)
            .unwrap_or_else(|e| panic!("failed to start hqckem_wrapper at {path:?}: {e}"))
    }

    fn decap_vs(vs_id: u64, param_set: &str, dk: &str, ct: &str) -> serde_json::Value {
        json!({
            "vsId": vs_id,
            "algorithm": "HQC",
            "mode": "encapDecap",
            "revision": "FIPS207",
            "testGroups": [{
                "tgId": 1,
                "testType": "AFT",
                "parameterSet": param_set,
                "function": "decapsulation",
                "tests": [{"tcId": 1, "dk": dk, "ct": ct}]
            }]
        })
    }

    // ── positive tests ────────────────────────────────────────────────────────

    #[test]
    fn decapsulation_recovers_shared_secret_hqc_128() {
        let vs = decap_vs(1, "HQC-128", DK_128, CT_128);
        let result = process_hqckem(&mut start_wrapper(), &vs).unwrap();
        let t = &result["testGroups"][0]["tests"][0];
        assert_eq!(t["k"].as_str().unwrap().to_uppercase(), K_128);
    }

    #[test]
    fn decapsulation_recovers_shared_secret_hqc_192() {
        let vs = decap_vs(2, "HQC-192", DK_192, CT_192);
        let result = process_hqckem(&mut start_wrapper(), &vs).unwrap();
        let t = &result["testGroups"][0]["tests"][0];
        assert_eq!(t["k"].as_str().unwrap().to_uppercase(), K_192);
    }

    #[test]
    fn decapsulation_recovers_shared_secret_hqc_256() {
        let vs = decap_vs(3, "HQC-256", DK_256, CT_256);
        let result = process_hqckem(&mut start_wrapper(), &vs).unwrap();
        let t = &result["testGroups"][0]["tests"][0];
        assert_eq!(t["k"].as_str().unwrap().to_uppercase(), K_256);
    }

    #[test]
    fn decapsulation_response_contains_required_fields() {
        let vs = decap_vs(4, "HQC-128", DK_128, CT_128);
        let result = process_hqckem(&mut start_wrapper(), &vs).unwrap();
        assert_eq!(result["vsId"], 4);
        assert_eq!(result["algorithm"], "HQC");
        let t = &result["testGroups"][0]["tests"][0];
        assert_eq!(t["tcId"], 1);
        assert!(t["k"].is_string());
        // shared secret K is 32 bytes -> 64 hex chars
        assert_eq!(t["k"].as_str().unwrap().len(), 64);
    }

    #[test]
    fn multiple_test_groups_processed_independently() {
        let vs = json!({
            "vsId": 5,
            "algorithm": "HQC",
            "mode": "encapDecap",
            "revision": "FIPS207",
            "testGroups": [
                {
                    "tgId": 1,
                    "parameterSet": "HQC-128",
                    "function": "decapsulation",
                    "tests": [{"tcId": 1, "dk": DK_128, "ct": CT_128}]
                },
                {
                    "tgId": 2,
                    "parameterSet": "HQC-192",
                    "function": "decapsulation",
                    "tests": [{"tcId": 2, "dk": DK_192, "ct": CT_192}]
                }
            ]
        });
        let result = process_hqckem(&mut start_wrapper(), &vs).unwrap();
        let groups = result["testGroups"].as_array().unwrap();
        assert_eq!(groups.len(), 2);
        assert_eq!(groups[0]["tgId"], 1);
        assert_eq!(groups[1]["tgId"], 2);
        assert_eq!(
            groups[0]["tests"][0]["k"].as_str().unwrap().to_uppercase(),
            K_128
        );
        assert_eq!(
            groups[1]["tests"][0]["k"].as_str().unwrap().to_uppercase(),
            K_192
        );
    }

    #[test]
    fn keygen_then_encaps_then_decaps_roundtrip_recovers_shared_secret() {
        // No official keyGen/encapsulation vectors were available alongside the
        // decapsulation KATs above, so this exercises keyGen + encaps + decaps
        // for internal consistency instead of against a fixed expected value.
        let mut wrapper = start_wrapper();

        let seed = "00".repeat(48);
        let keygen_vs = json!({
            "vsId": 6,
            "algorithm": "HQC",
            "mode": "keyGen",
            "revision": "FIPS207",
            "testGroups": [{
                "tgId": 1,
                "parameterSet": "HQC-128",
                "tests": [{"tcId": 1, "seed": seed}]
            }]
        });
        let keygen_result = process_hqckem(&mut wrapper, &keygen_vs).unwrap();
        let ek = keygen_result["testGroups"][0]["tests"][0]["ek"]
            .as_str()
            .unwrap()
            .to_string();

        let m = "11".repeat(32);
        let encaps_vs = json!({
            "vsId": 7,
            "algorithm": "HQC",
            "mode": "encapDecap",
            "revision": "FIPS207",
            "testGroups": [{
                "tgId": 1,
                "parameterSet": "HQC-128",
                "function": "encapsulation",
                "tests": [{"tcId": 1, "ek": ek, "m": m}]
            }]
        });
        let encaps_result = process_hqckem(&mut wrapper, &encaps_vs).unwrap();
        let ct = encaps_result["testGroups"][0]["tests"][0]["c"]
            .as_str()
            .unwrap()
            .to_string();
        let k_encaps = encaps_result["testGroups"][0]["tests"][0]["k"]
            .as_str()
            .unwrap()
            .to_string();

        let dk = keygen_result["testGroups"][0]["tests"][0]["dk"]
            .as_str()
            .unwrap()
            .to_string();
        let decaps_vs = json!({
            "vsId": 9,
            "algorithm": "HQC",
            "mode": "encapDecap",
            "revision": "FIPS207",
            "testGroups": [{
                "tgId": 1,
                "parameterSet": "HQC-128",
                "function": "decapsulation",
                "tests": [{"tcId": 1, "dk": dk, "ct": ct}]
            }]
        });
        let decaps_result = process_hqckem(&mut wrapper, &decaps_vs).unwrap();
        let k_decaps = decaps_result["testGroups"][0]["tests"][0]["k"]
            .as_str()
            .unwrap()
            .to_string();

        assert_eq!(k_encaps, k_decaps);
    }

    // ── negative tests ────────────────────────────────────────────────────────

    #[test]
    fn unknown_mode_returns_error() {
        let vs = json!({
            "vsId": 20,
            "algorithm": "HQC",
            "mode": "badMode",
            "revision": "FIPS207",
            "testGroups": [{
                "tgId": 1,
                "parameterSet": "HQC-128",
                "tests": [{"tcId": 1, "dk": DK_128, "ct": CT_128}]
            }]
        });
        assert!(process_hqckem(&mut start_wrapper(), &vs).is_err());
    }

    #[test]
    fn unknown_function_in_encapdecap_returns_error() {
        let vs = json!({
            "vsId": 21,
            "algorithm": "HQC",
            "mode": "encapDecap",
            "revision": "FIPS207",
            "testGroups": [{
                "tgId": 1,
                "parameterSet": "HQC-128",
                "function": "badFunction",
                "tests": [{"tcId": 1, "dk": DK_128, "ct": CT_128}]
            }]
        });
        assert!(process_hqckem(&mut start_wrapper(), &vs).is_err());
    }

    #[test]
    fn missing_mode_field_returns_error() {
        let vs = json!({
            "vsId": 22,
            "algorithm": "HQC",
            "revision": "FIPS207",
            "testGroups": [{"tgId": 1, "parameterSet": "HQC-128", "tests": []}]
        });
        assert!(process_hqckem(&mut start_wrapper(), &vs).is_err());
    }

    #[test]
    fn missing_function_field_in_encapdecap_returns_error() {
        let vs = json!({
            "vsId": 23,
            "algorithm": "HQC",
            "mode": "encapDecap",
            "revision": "FIPS207",
            "testGroups": [{
                "tgId": 1,
                "parameterSet": "HQC-128",
                // function field absent
                "tests": [{"tcId": 1, "dk": DK_128, "ct": CT_128}]
            }]
        });
        assert!(process_hqckem(&mut start_wrapper(), &vs).is_err());
    }

    #[test]
    fn unimplemented_parameter_set_is_reported_unsupported_not_fatal() {
        // hqckem-ref only implements HQC-128/192/256; any other name falls
        // through to its `todo!()` arm and panics. The wrapper must catch
        // that and reply "unsupported" instead of taking down the whole
        // connection, so processing can continue with the next test case.
        let vs = json!({
            "vsId": 30,
            "algorithm": "HQC",
            "mode": "keyGen",
            "revision": "FIPS207",
            "testGroups": [{
                "tgId": 1,
                "parameterSet": "HQC-does-not-exist",
                "tests": [{"tcId": 1, "seed": "00"}]
            }]
        });
        let mut subprocess = start_wrapper();
        let result = process_hqckem(&mut subprocess, &vs).unwrap();
        assert!(result["testGroups"][0]["tests"]
            .as_array()
            .unwrap()
            .is_empty());
        assert_eq!(subprocess.unsupported_count(), 1);
    }

    #[test]
    fn missing_dk_field_returns_error() {
        let vs = json!({
            "vsId": 24,
            "algorithm": "HQC",
            "mode": "encapDecap",
            "revision": "FIPS207",
            "testGroups": [{
                "tgId": 1,
                "parameterSet": "HQC-128",
                "function": "decapsulation",
                "tests": [{"tcId": 1, "ct": CT_128}]  // dk is absent
            }]
        });
        assert!(process_hqckem(&mut start_wrapper(), &vs).is_err());
    }

    #[test]
    fn invalid_hex_in_dk_returns_error() {
        let vs = json!({
            "vsId": 25,
            "algorithm": "HQC",
            "mode": "encapDecap",
            "revision": "FIPS207",
            "testGroups": [{
                "tgId": 1,
                "parameterSet": "HQC-128",
                "function": "decapsulation",
                "tests": [{"tcId": 1, "dk": "ZZZZNOTHEX!", "ct": CT_128}]
            }]
        });
        assert!(process_hqckem(&mut start_wrapper(), &vs).is_err());
    }
}
